package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build dynamic query
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	if category != "" {
		query += " AND category = '" + category + "'"
	}

	if minPrice != "" {
		query += " AND price >= " + minPrice
	}

	if maxPrice != "" {
		query += " AND price <= " + maxPrice
	}

	// Sort validation - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy != "" && allowedSorts[sortBy] {
		query += " ORDER BY " + sortBy
	} else {
		query += " ORDER BY id"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(","))
		}
		// Manual JSON construction to avoid reflection overhead
		json := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price,
			strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(json))
		first = false
	}
	w.Write([]byte("]"))
}

// getProductDetail returns a single product - uses parameterized query
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	row := db.QueryRow("SELECT id, name, price, description FROM products WHERE id = $1", id)
	var pid int
	var name, description string
	var price float64
	if err := row.Scan(&pid, &name, &price, &description); err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
		pid, strings.ReplaceAll(name, `"`, `\"`), price,
		strings.ReplaceAll(description, `"`, `\"`))
	w.Write([]byte(json))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.ListenAndServe(":8080", nil)
}
